def matchesAbbreviation(word, abbr):
    n, m = len(word), len(abbr)
    i = j = 0
    while j < m:
        c = abbr[j]
        if '0' <= c <= '9':
            if c == '0':
                return False
            k = 0
            while j < m and '0' <= abbr[j] <= '9':
                k = k * 10 + ord(abbr[j]) - 48
                j += 1
            i += k
            if i > n:
                return False
        else:
            if i >= n or word[i] != c:
                return False
            i += 1
            j += 1
    return i == n
